import json, os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(ROOT); sys.path.insert(0, os.path.join(ROOT, 'models/freecad'))
import params as P

g = json.load(open('flow_graph/plant_flow_graph.json')); N = {n['unit_id']: n for n in g['nodes']}
crew = int(float((N['HABITATION'].get('params') or {}).get('crew_study')))
FIXTURE_CREW = 4   # the crew size for which the fixture counts of Table 3.1 were made
recount = crew != FIXTURE_CREW

